local function warnf(...)
    warn("[" .. Config.Name .. "]", ...)
end

-- Penampung koneksi / instance / fungsi cleanup supaya Unload bisa bersih total.
local Janitor = {}
local function track(item)
    Janitor[#Janitor + 1] = item
    return item
end

local function connect(signal, fn)
    return track(signal:Connect(fn))
end

local function safe(fn, ...)
    local ok, err = pcall(fn, ...)
    if not ok then
        warnf(tostring(err))
    end
    return ok
end

local warned = {}
local function safeOnce(fn, ...)
    local ok, err = pcall(fn, ...)
    if not ok then
        local key = tostring(err)
        if not warned[key] then
            warned[key] = true
            warnf(key)
        end
    end
    return ok
end

local function copyText(text)
    local fn = setclipboard or toclipboard
    if fn then
        return pcall(fn, text)
    end
    return false
end

local function getChar(p)
    return p and p.Character
end

local function getHum(p)
    local c = getChar(p)
    return c and c:FindFirstChildOfClass("Humanoid")
end

local function getRoot(p)
    local c = getChar(p)
    return c and (c:FindFirstChild("HumanoidRootPart") or c.PrimaryPart)
end

local function getCamera()
    return workspace.CurrentCamera
end

local function randomName()
    local ok, guid = pcall(function()
        return HttpService:GenerateGUID(false)
    end)
    if ok and guid then
        return guid
    end
    return tostring(math.random(100000, 999999)) .. tostring(os.clock())
end

