    function G.roleEnabled(roleName)
        if roleName == nil then
            return false
        end
        local cfg = G.require("shared.configurations.seasonalRolesConfig")
        local enabled = type(cfg) == "table" and rawget(cfg, "enabled") or nil
        if type(enabled) ~= "table" then
