    local function resolveAnimEntry(e)
        if e.fromModule then
            return moduleAnimValue(e)
        end
        local v = e.value
        -- Animation yang sudah di-Destroy (Parent nil) bisa masih ada di cache scan
        if isAnimation(v) and idx(v, "Parent") ~= nil then
            return v
        end
        return nil
    end

    local function findAnim(names, avoid)
        return matchByName(animEntries(), names, resolveAnimEntry, avoid)
    end

    local function sameAnim(a, b)
        if a == nil or b == nil then
            return false
        end
        if a == b then
            return true
        end
        local ok, r = pcall(function()
            local ia, ib = Game.normalizeId(a.AnimationId), Game.normalizeId(b.AnimationId)
            return ia ~= nil and ia ~= "0" and ia == ib
        end)
        return ok and r == true
    end

    local function renderPriority(name, delta)
        local ok, v = pcall(function()
            return Enum.RenderPriority[name].Value
        end)
        if ok and type(v) == "number" then
            return v + delta
        end
        return nil
    end

    local function bindRender(name, priority, fn)
        if type(priority) ~= "number" then
            return false
        end
        local ok = pcall(function()
            RunService:BindToRenderStep(name, priority, fn)
        end)
        return ok
    end

    local function unbindRender(name)
        pcall(function()
            RunService:UnbindFromRenderStep(name)
        end)
    end

    -- Pindahkan karakter lokal. PivotTo kalau PrimaryPart = root, selain itu set root.CFrame (assembly ikut).
    local function placeAt(char, root, cf)
        local ok = false
        if char and char.PrimaryPart == root then
            ok = pcall(function()
                char:PivotTo(cf)
            end)
        end
        if not ok then
            ok = pcall(function()
                root.CFrame = cf
            end)
        end
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        return ok
    end

    -- Posisi `dist` stud di belakang target (LookVector didatarkan), menghadap target, tetap tegak.
    local function standCF(targetCF, dist)
        local pos = targetCF.Position
        local look = targetCF.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude < 0.01 then
            flat = Vector3.new(0, 0, -1)
        else
            flat = flat.Unit
        end
        local dest = pos - flat * dist
        return CFrame.new(dest, Vector3.new(pos.X, dest.Y, pos.Z))
    end

    ------------------------------------------------------------------
    -- State
    ------------------------------------------------------------------
    local Target = { player = nil }
    local Busy = { on = false }
    local Last = { method = nil }
    local Crawl = {
        on = false, hb = nil, st = nil, hum = nil, crawl = nil, idle = nil, crawlAnim = nil, idleAnim = nil,
        mode = nil, still = 0, flagT = 0, paused = false, saved = nil, speed = 4, wrote = false, retry = 0,
    }
    local Shot = { last = {}, token = {}, tracks = {} }
    local Ghost = { on = false, hb = nil, died = nil, char = nil, pending = nil, suspended = false, bound = false }
    local Bring = { on = false, conn = nil, bound = false, player = nil, root = nil, real = nil, lastSet = nil, checkT = 0 }
    local GHOST_BIND = "NoctisENIX_GhostRestore"
    local BRING_BIND = "NoctisENIX_Bring"

    ------------------------------------------------------------------
    -- Animasi
    ------------------------------------------------------------------
    -- priorityName: prioritas lebih tinggi (mis. "Action4") supaya one-shot tidak dicampur 50/50 dengan
    -- track crawl yang juga Action; fallback ke Action kalau enum itu tidak ada di engine ini.
    local function loadTrack(animator, anim, looped, priorityName)
        local ok, track = pcall(function()
            return animator:LoadAnimation(anim)
        end)
        if not ok or not track then
            return nil
        end
        pcall(function()
            track.Looped = looped
        end)
        local okP = false
        if priorityName then
            okP = pcall(function()
                local pr = Enum.AnimationPriority[priorityName]
                if pr == nil then
                    error("no priority")
                end
                track.Priority = pr
            end)
        end
        if not okP then
            pcall(function()
                track.Priority = Enum.AnimationPriority.Action
            end)
        end
        return track
    end

    local function stopTrack(track, fade)
        if track then
            pcall(function()
                track:Stop(fade)
            end)
        end
    end

    local function dropTrack(track)
        if not track then
            return
        end
        stopTrack(track, 0.2)
        task.delay(0.3, function()
            pcall(function()
                track:Destroy()
            end)
        end)
    end

    ------------------------------------------------------------------
    -- Fake crawl
    ------------------------------------------------------------------
    local function crawlSpeed()
        local v = setting("crawlSpeed", nil)
        if type(v) == "number" and v > 0 then
            return v
        end
        for _, k in ipairs({ "crawlSpeed", "CrawlSpeed", "crawlWalkSpeed", "downedWalkSpeed", "downedSpeed", "woundedWalkSpeed", "woundedSpeed" }) do
            local ok, n = pcall(Game.configNumber, k, nil)
            if ok and type(n) == "number" and n > 0 then
                return n
            end
        end
        return 4
    end

    local function crawlRelease()
        dropTrack(Crawl.crawl)
        dropTrack(Crawl.idle)
        Crawl.crawl, Crawl.idle, Crawl.mode = nil, nil, nil
    end

    -- Balikin WalkSpeed cuma kalau nilainya masih punya kita (tidak diubah game / fitur lain).
    local function crawlRestoreSpeed()
        local hum = Crawl.hum
        if Crawl.wrote and hum and Crawl.saved then
            pcall(function()
                if math.abs(hum.WalkSpeed - Crawl.speed) < 0.01 then
                    hum.WalkSpeed = Crawl.saved
                end
            end)
        end
        Crawl.wrote = false
    end

    local function crawlBind(hum)
        local animator = hum:FindFirstChildOfClass("Animator")
        if not animator then
            return false
        end
        crawlRelease()
        local track = loadTrack(animator, Crawl.crawlAnim, true)
        if not track then
            return false
        end
        Crawl.hum = hum
        Crawl.saved = hum.WalkSpeed
        Crawl.wrote = false
        Crawl.crawl = track
        if Crawl.idleAnim then
            Crawl.idle = loadTrack(animator, Crawl.idleAnim, true)
        end
        Crawl.mode = nil
        Crawl.still = 0
        return true
    end

    local function crawlSetMode(mode)
        local c, i = Crawl.crawl, Crawl.idle
        if mode == "move" then
            stopTrack(i, 0.2)
            if c then
                pcall(function()
                    if not c.IsPlaying then
                        c:Play(0.2)
                    end
                    c:AdjustSpeed(1)
                end)
            end
        elseif mode == "idle" then
            if i then
                stopTrack(c, 0.2)
                pcall(function()
                    if not i.IsPlaying then
                        i:Play(0.2)
                    end
                end)
            elseif c then
                -- tidak ada anim idle: bekukan pose crawl
                pcall(function()
                    if not c.IsPlaying then
                        c:Play(0.2)
                    end
                    c:AdjustSpeed(0)
                end)
            end
        else
            stopTrack(c, 0.2)
            stopTrack(i, 0.2)
        end
        Crawl.mode = mode
    end

    local function crawlModePlaying(mode)
        local track = Crawl.crawl
        if mode == "idle" and Crawl.idle then
            track = Crawl.idle
        end
        if not track then
            return true
        end
        local ok, playing = pcall(function()
            return track.IsPlaying
        end)
        return not ok or playing == true
    end

    local function crawlStep(dt)
        if not Crawl.on or not live() then
            return
        end
        dt = tonumber(dt) or 0
        local _, hum = body(LocalPlayer)
        if not hum or hum.Health <= 0 then
            return
        end
        if hum ~= Crawl.hum then
            -- respawn: muat ulang track di Animator baru (kalau sudah ada), coba lagi tiap 0.5 s
            Crawl.retry = Crawl.retry - dt
            if Crawl.retry > 0 then
                return
            end
            if not crawlBind(hum) then
                Crawl.retry = 0.5
                return
            end
            Crawl.retry = 0
            Crawl.flagT = 1
        end
        -- beneran downed? biarkan game yang animasiin (cek tiap 0.25 s, bukan tiap frame)
        local recheck = false
        Crawl.flagT = Crawl.flagT + dt
        if Crawl.flagT >= 0.25 then
            Crawl.flagT = 0
            recheck = true
            local was = Crawl.paused
            Crawl.paused = flag(LocalPlayer, "Downed")
            if Crawl.paused and not was then
                crawlSetMode(nil)
                Crawl.wrote = false
            end
        end
        if Crawl.paused then
            return
        end
        if not setting("crawlKeepSpeed", false) then
            if hum.WalkSpeed ~= Crawl.speed then
                hum.WalkSpeed = Crawl.speed
            end
            Crawl.wrote = true
        elseif Crawl.wrote then
            -- crawlKeepSpeed baru dinyalakan di tengah crawl: balikin speed normal sekarang
            crawlRestoreSpeed()
        end
        local mag = 0
        pcall(function()
            mag = hum.MoveDirection.Magnitude
        end)
        -- hysteresis: mulai jalan langsung, berhenti setelah diam 0.12 s
        local want = Crawl.mode
        if mag > 0.05 then
            Crawl.still = 0
            want = "move"
        elseif mag < 0.02 then
            Crawl.still = Crawl.still + dt
            if Crawl.mode ~= "move" or Crawl.still >= 0.12 then
                want = "idle"
            end
        end
        if want == nil then
            want = "idle"
        end
        -- recheck: track kita bisa di-Stop game (Animate, equip tool, ganti state) -> putar lagi
        if want ~= Crawl.mode or (recheck and not crawlModePlaying(want)) then
            crawlSetMode(want)
        end
    end

    -- Stepped jalan tepat sebelum physics: speed crawl menang dari penulis WalkSpeed lain di Heartbeat
    -- (mis. speed hack script utama), urutan koneksi Heartbeat tidak dijamin.
    local function crawlPhysicsStep()
        if not Crawl.on or Crawl.paused or not Crawl.wrote then
            return
        end
        local hum = Crawl.hum
        if not hum or setting("crawlKeepSpeed", false) then
            return
        end
        pcall(function()
            if hum.Parent and hum.WalkSpeed ~= Crawl.speed then
                hum.WalkSpeed = Crawl.speed
            end
        end)
    end

    local function crawlOff()
        Crawl.on = false
        Crawl.hb = disconnect(Crawl.hb)
        Crawl.st = disconnect(Crawl.st)
        crawlRelease()
        crawlRestoreSpeed()
        Crawl.hum = nil
        Crawl.paused = false
    end

    function Actions.setFakeCrawl(on)
        if not on then
            if not Crawl.on then
                return true, "Fake crawl is already off."
            end
            crawlOff()
            return true, "Fake crawl off."
        end
        if Crawl.on then
            return true, "Fake crawl is already on."
        end
        local char, hum = myBody()
        if not char then
            return false, MSG.noBodyAct
        end
        if flag(LocalPlayer, "Downed") then
            return false, MSG.reallyDowned
        end
        local crawlAnim = findAnim({ "Wounded Crawling", "crawl", "Crawling" })
        if not crawlAnim then
            return false, MSG.noCrawlAnim
        end
        local idleAnim = findAnim({ "Wounded Idle", "wounded" }, { "crawl" })
        if sameAnim(idleAnim, crawlAnim) then
            idleAnim = nil
        end
        if not hum:FindFirstChildOfClass("Animator") then
            return false, MSG.noAnimator
        end
        Crawl.crawlAnim, Crawl.idleAnim = crawlAnim, idleAnim
        Crawl.speed = crawlSpeed()
        Crawl.hum = nil
        Crawl.paused = false
        Crawl.flagT = 0
        Crawl.retry = 0
        if not crawlBind(hum) then
            return false, "Could not load the crawl animation."
        end
        Crawl.on = true
        Crawl.hb = connect(RunService.Heartbeat, crawlStep)
        local stepped = idx(RunService, "Stepped")
        if stepped then
            Crawl.st = connect(stepped, crawlPhysicsStep)
        end
        crawlStep(0)
        return true, "Everyone sees you crawling wounded."
    end

    ------------------------------------------------------------------
    -- Fake stab / fake gunshot (cuma animasi: tanpa equip tool, tanpa remote)
    ------------------------------------------------------------------
    -- pose yang bukan aksi (KnifeIdle, KnifeEquip, ...) tidak boleh menang lewat substring "knife"
    local ONE_SHOT_AVOID = { "idle", "equip", "hold", "walk", "run", "sprint", "jump", "crawl", "wound", "pose" }

    local function oneShot(kind, names, label)
        local t = now()
        local last = Shot.last[kind]
        if last and t - last < 0.6 then
            return false, MSG.cooldown
        end
        local char, hum = myBody()
        if not char then
            return false, MSG.noBodyAct
        end
        local animator = hum:FindFirstChildOfClass("Animator")
        if not animator then
            return false, MSG.noAnimator
        end
        local anim = findAnim(names, ONE_SHOT_AVOID)
        if not anim then
            return false, label .. " animation not found in this game version."
        end
        local cache = Shot.tracks[kind]
        local track = nil
        if cache and cache.animator == animator and cache.anim == anim then
            track = cache.track
        end
        if not track then
            if cache then
                pcall(function()
                    cache.track:Destroy()
                end)
            end
            track = loadTrack(animator, anim, false, "Action4")
            if not track then
                return false, "Could not load " .. tostring(anim.Name) .. "."
            end
            Shot.tracks[kind] = { animator = animator, anim = anim, track = track }
        end
        local okPlay = pcall(function()
            if track.IsPlaying then
                track:Stop(0)
            end
            track:Play(0.05)
        end)
        if not okPlay then
            return false, "Could not play " .. tostring(anim.Name) .. "."
        end
        Shot.last[kind] = t
        local tok = (Shot.token[kind] or 0) + 1
        Shot.token[kind] = tok
        local len = 0
        pcall(function()
            len = track.Length
        end)
        -- Length = 0 kalau asset belum ke-load
        if type(len) ~= "number" or len <= 0 then
            len = 1
        elseif len > 4 then
            len = 4
        end
        task.delay(len, function()
            if Shot.token[kind] == tok then
                stopTrack(track, 0.15)
            end
        end)
        return true, "Played " .. tostring(anim.Name)
    end

    function Actions.fakeStab()
        return oneShot("stab", { "KnifeSwing" }, "Stab")
    end

    function Actions.fakeShot()
        return oneShot("shot", { "Glock" }, "Gunshot")
    end

    ------------------------------------------------------------------
    -- Ghost (CFrame desync)
    -- Heartbeat: geser root ke bawah map -> replikasi kirim posisi palsu -> render berikutnya balikin.
    -- Catatan: server bisa rubber-band atau nge-flag ini (anti-teleport). Pakai dengan risiko sendiri.
    ------------------------------------------------------------------
    local function ghostRestore()
        local p = Ghost.pending
        if not p then
            return
        end
        Ghost.pending = nil
        if p.root.Parent and p.char == LocalPlayer.Character then
            pcall(function()
                -- game memindahkan kita di antara Heartbeat dan render (kursi meeting, reset ronde)?
                -- posisi baru itu yang dipakai, jangan ditimpa posisi lama
                if (p.root.CFrame.Position - p.shifted.Position).Magnitude > 2 then
                    return
                end
                p.root.CFrame = p.cf
                p.root.AssemblyLinearVelocity = p.vel
            end)
        end
    end

    local ghostOff
    local function ghostBeat()
        -- satu frame in-flight saja (anti numpuk)
        if not Ghost.on or Ghost.pending or Ghost.suspended or not live() then
            return
        end
        local char, hum, root = body(LocalPlayer)
        if char ~= Ghost.char or not (hum and root) or hum.Health <= 0 then
            ghostOff("Ghost turned off (your character changed).")
            return
        end
        if isSeated(hum) then
            return
        end
        local depth = tonumber(setting("ghostDepth", 40)) or 40
        local okSave, cf, vel = pcall(function()
            return root.CFrame, root.AssemblyLinearVelocity
        end)
        if not okSave then
            return
        end
        local okShift, shifted = pcall(function()
            return cf + Vector3.new(0, -depth, 0)
        end)
        if not okShift then
            return
        end
        Ghost.pending = { root = root, char = char, cf = cf, vel = vel, shifted = shifted }
        local okSet = pcall(function()
            root.CFrame = shifted
        end)
        if not okSet then
            Ghost.pending = nil
            return
        end
        -- Kalau BindToRenderStep jalan, restore terjadi di prioritas First (sebelum kamera).
        -- Wait ini cadangan; ghostRestore idempotent.
        pcall(function()
            RunService.RenderStepped:Wait()
        end)
        ghostRestore()
    end

    ghostOff = function(reason)
        local was = Ghost.on
        Ghost.on = false
        Ghost.hb = disconnect(Ghost.hb)
        Ghost.died = disconnect(Ghost.died)
        if Ghost.bound then
            unbindRender(GHOST_BIND)
            Ghost.bound = false
        end
        -- jangan pernah tinggalkan karakter di bawah map
        ghostRestore()
        Ghost.char = nil
        if was and reason then
            notify("Ghost", reason)
        end
    end

    function Actions.setGhost(on)
        if not on then
            if not Ghost.on then
                return true, "Ghost is already off."
            end
            ghostOff(nil)
            return true, "Ghost off. Everyone sees you where you really are."
        end
        if Ghost.on then
            return true, "Ghost is already on."
        end
        local char, hum = myBody()
        if not char then
            return false, MSG.noBodyAct
        end
        if isSeated(hum) then
            return false, MSG.seated
        end
        Ghost.on = true
        Ghost.char = char
        Ghost.pending = nil
        Ghost.suspended = false
        Ghost.hb = connect(RunService.Heartbeat, ghostBeat)
        Ghost.died = connect(hum.Died, function()
            ghostOff("Ghost turned off (you died).")
        end)
        Ghost.bound = bindRender(GHOST_BIND, renderPriority("First", 0), ghostRestore)
        return true, "Others see you under the map. You cannot stab, heal or interact while it is on."
    end

    ------------------------------------------------------------------
    -- Target
    ------------------------------------------------------------------
    local bringOff, bringRetarget

    function Actions.livingPlayers()
        local out = {}
        pcall(function()
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LocalPlayer and alive(p) then
                    out[#out + 1] = p
                end
            end
        end)
        pcall(table.sort, out, function(a, b)
            local na, nb = string.lower(nameOf(a)), string.lower(nameOf(b))
            if na == nb then
                return tostring(a.Name) < tostring(b.Name)
            end
            return na < nb
        end)
        return out
    end

    function Actions.getTarget()
        local p = Target.player
        if p and (p == LocalPlayer or not alive(p)) then
            Target.player = nil
            p = nil
        end
        return p
    end

    function Actions.setTarget(p)
        if p == nil then
            Target.player = nil
            if Bring.on then
                bringOff("Target cleared, bring turned off.")
            end
            return true, "Target cleared."
        end
        local okP, isPlr = pcall(function()
            return typeof(p) == "Instance" and p:IsA("Player")
        end)
        if not (okP and isPlr) then
            return false, "That is not a player."
        end
        if p == LocalPlayer then
            return false, "You cannot target yourself."
        end
        if not alive(p) then
            return false, MSG.noTarget
        end
        Target.player = p
        -- bring ikut pindah ke target baru (target lama dibalikin ke posisi aslinya)
        if Bring.on and Bring.player ~= p then
            bringRetarget(p)
        end
        return true, "Target: " .. nameOf(p)
    end

    ------------------------------------------------------------------
    -- Bring target (client-side saja; server tetap otoritas, replikasi menimpa tiap frame)
    ------------------------------------------------------------------
    -- CFrame target yang asli (bukan hasil bring kita)
    local function realTargetCF(p)
        local _, _, r = body(p)
        if not r then
            return nil
        end
        if Bring.on and Bring.player == p and Bring.root == r and Bring.real then
            return Bring.real
        end
        local ok, cf = pcall(function()
            return r.CFrame
        end)
        if ok then
            return cf
        end
        return nil
    end

    -- Tulis balik posisi asli target. Penting kalau tidak ada update replikasi yang menimpa posisi bring
    -- (target diam, atau duduk di kursi anchored lewat SeatWeld saat meeting). Kalau CFrame sekarang sudah
    -- bukan yang kita set, itu update replikasi yang lebih baru: biarkan.
    local function bringRestoreReal()
        local r, real, set = Bring.root, Bring.real, Bring.lastSet
        Bring.lastSet = nil
        if not (r and real and set) then
            return
        end
        pcall(function()
            if r.Parent and r.CFrame == set then
                r.CFrame = real
            end
        end)
    end

    bringOff = function(reason)
        local was = Bring.on
        Bring.on = false
        if Bring.bound then
            unbindRender(BRING_BIND)
            Bring.bound = false
        end
        Bring.conn = disconnect(Bring.conn)
        bringRestoreReal()
        Bring.player, Bring.root, Bring.real, Bring.lastSet = nil, nil, nil, nil
        if was and reason then
            notify("Bring target", reason)
        end
    end

    bringRetarget = function(p)
        bringRestoreReal()
        local _, _, r = body(p)
        Bring.player, Bring.root, Bring.real, Bring.lastSet, Bring.checkT = p, r, nil, nil, now()
    end

    local function bringStep()
        if not Bring.on then
            return
        end
        if not live() then
            bringOff(nil)
            return
        end
        local t = now()
        local p, tRoot = Bring.player, Bring.root
        -- validasi target (isAlive) dibatasi 4x per detik
        if t - Bring.checkT >= 0.25 or not (tRoot and tRoot.Parent) then
            Bring.checkT = t
            local np = Actions.getTarget()
            local _, _, r = body(np)
            if not (np and r and r.Parent) then
                bringOff("Target lost, bring turned off.")
                return
            end
            if np ~= Bring.player or r ~= Bring.root then
                bringRestoreReal()
                Bring.real = nil
            end
            Bring.player, Bring.root = np, r
            p, tRoot = np, r
        end
        if not (p and tRoot and tRoot.Parent) then
            bringOff("Target lost, bring turned off.")
            return
        end
        local _, _, myRoot = body(LocalPlayer)
        if not myRoot then
            return
        end
        pcall(function()
            local cur = tRoot.CFrame
            -- beda dari yang kita set = update replikasi baru = posisi asli
            if Bring.lastSet == nil or cur ~= Bring.lastSet then
                Bring.real = cur
            end
            -- selama TSR / THR target ditaruh balik di posisi asli (cek jarak / hitbox di client game)
            if Busy.on then
                bringRestoreReal()
                return
            end
            local myCF = myRoot.CFrame
            local pos = (myCF * CFrame.new(0, 0, -6)).Position
            local myPos = myCF.Position
            local cf = CFrame.new(pos, Vector3.new(myPos.X, pos.Y, myPos.Z))
            tRoot.CFrame = cf
            Bring.lastSet = cf
        end)
    end

    function Actions.setBring(on)
        if not on then
            bringOff(nil)
            return true, "Bring off."
        end
        local p = Actions.getTarget()
        if not p then
            return false, MSG.noTarget
        end
        local _, _, r = body(p)
        if not r then
            return false, MSG.noTargetBody
        end
        if not myBody() then
            return false, MSG.noBodyAct
        end
        bringOff(nil)
        Bring.on = true
        Bring.player, Bring.root, Bring.checkT = p, r, now()
        Bring.bound = bindRender(BRING_BIND, renderPriority("Camera", -1), bringStep)
        if not Bring.bound then
            Bring.conn = connect(RunService.RenderStepped, bringStep)
        end
        return true, MSG.bring
    end

    ------------------------------------------------------------------
    -- Teleport
    ------------------------------------------------------------------
    local function nearestWith(flagName)
        local _, _, myRoot = body(LocalPlayer)
        local myPos = nil
        if myRoot then
            pcall(function()
                myPos = myRoot.CFrame.Position
            end)
        end
        local best, bestD = nil, nil
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and alive(p) and flag(p, flagName) then
                -- posisi asli (bukan posisi palsu hasil Bring)
                local cf = realTargetCF(p)
                if cf then
                    local d = 0
                    if myPos then
                        pcall(function()
                            d = (cf.Position - myPos).Magnitude
                        end)
                    end
                    if not best or d < bestD then
                        best, bestD = p, d
                    end
                end
            end
        end
        return best
    end

    local function teleportNear(p)
        local char, hum, root = myBody()
        if not char then
            return false, MSG.noBody
        end
        if isSeated(hum) then
            return false, MSG.seated
        end
        local tcf = realTargetCF(p)
        if not tcf then
            return false, MSG.noTargetBody
        end
        ghostRestore()
        local okCF, dest = pcall(standCF, tcf, tonumber(setting("tpDistance", 3)) or 3)
        if not okCF or not placeAt(char, root, dest) then
            return false, "Teleport failed."
        end
        return true, "Teleported to " .. nameOf(p) .. "."
    end

    function Actions.toTarget()
        local p = Actions.getTarget()
        if not p then
            return false, MSG.noTarget
        end
        return teleportNear(p)
    end

    function Actions.toDowned()
        local ok, p = pcall(nearestWith, "Downed")
        if not (ok and p) then
            return false, MSG.noDowned
        end
        return teleportNear(p)
    end

    function Actions.toDetained()
        local ok, p = pcall(nearestWith, "Detained")
        if not (ok and p) then
            return false, MSG.noDetained
        end
        return teleportNear(p)
    end

    ------------------------------------------------------------------
    -- Handler game (roleController.roles.mafia / doctor)
    ------------------------------------------------------------------
    local STAB_FNS = { "handleMafiaStab", "handleStab", "tryStab", "attemptStab" }
    local HEAL_WORDS = { "heal", "revive", "save", "pick" }
    local SKIP_FIRST = {}
    for _, w in ipairs({ "set", "get", "is", "can", "has", "on", "init", "start", "setup", "update", "render", "play", "show", "hide", "destroy", "clean" }) do
        SKIP_FIRST[w] = true
    end

    -- "handleDoctorSave" / "Revive_Prompt" / "Pick up" -> { "handle", "doctor", "save" } dst (huruf kecil)
    local function nameWords(s)
        local out = {}
        s = tostring(s or "")
        s = string.gsub(s, "(%l)(%u)", "%1 %2")
        s = string.gsub(s, "(%u)(%u%l)", "%1 %2")
        for w in string.gmatch(string.lower(s), "%a+") do
            out[#out + 1] = w
        end
        return out
    end

    -- Kata utuh + imbuhan umum: heal/heals/healed/healing/healer, revive/reviving, stab/stabbing.
    -- "health" TIDAK cocok dengan "heal".
    local WORD_SUFFIX = { [""] = true, s = true, ed = true, ing = true, er = true }
    local function hasWord(tokens, w)
        local stem = nil
        if string.sub(w, -1) == "e" then
            stem = string.sub(w, 1, -2)
        end
        local dbl = w .. string.sub(w, -1)
        for _, t in ipairs(tokens) do
            if string.sub(t, 1, #w) == w and WORD_SUFFIX[string.sub(t, #w + 1)] then
                return true
            end
            if stem and (t == stem .. "ing" or t == stem .. "ed") then
                return true
            end
            if t == dbl .. "ing" or t == dbl .. "ed" then
                return true
            end
        end
        return false
    end

    -- index kata pertama di `list` yang ada di tokens, atau nil
    local function firstWord(tokens, list)
        for i, w in ipairs(list) do
            if hasWord(tokens, w) then
                return i
            end
        end
        return nil
    end

    local function exactFn(host, names)
        for _, n in ipairs(names) do
            local f = fnOf(host, n)
            if f then
                return n, f
            end
        end
        return nil, nil
    end

    -- Fungsi aksi berdasarkan kata di namanya (juga method di metatable __index).
    local function wordFn(host, words)
        if type(host) ~= "table" then
            return nil, nil
        end
        local found = {}
        local function scan(t)
            pcall(function()
                for k, v in pairs(t) do
                    if type(k) == "string" and type(v) == "function" and found[k] == nil then
                        found[k] = v
                    end
                end
            end)
        end
        scan(host)
        local okMt, mt = pcall(getmetatable, host)
        if okMt and type(mt) == "table" and type(rawget(mt, "__index")) == "table" then
            scan(rawget(mt, "__index"))
        end
        -- handle* selalu di depan, lalu urutan kata; kata utuh saja (healthChanged bukan "heal")
        local best, bestScore, bestFn = nil, nil, nil
        for name, fn in pairs(found) do
            local toks = nameWords(name)
            if toks[1] and not SKIP_FIRST[toks[1]] then
                local i = firstWord(toks, words)
                if i then
                    local score = i * 10
                    if toks[1] ~= "handle" then
                        score = score + 100
                    end
                    if not best or score < bestScore or (score == bestScore and name < best) then
                        best, bestScore, bestFn = name, score, fn
                    end
                end
            end
        end
        return best, bestFn
    end

    -- strict: dipakai untuk tabel yang bukan modul role khusus (roleController sendiri, field-nya, getgc),
    -- supaya fungsi lain seperti pickDisguise tidak ikut terpanggil.
    local STRICT_HEAL_WORDS = { "heal", "revive" }
    local HOSTS = {
        mafia = {
            path = "client.controllers.roleController.roles.mafia",
            keys = { "mafia", "Mafia" },
            test = function(t, strict)
                return (exactFn(t, STAB_FNS)) ~= nil
            end,
        },
        doctor = {
            path = "client.controllers.roleController.roles.doctor",
            keys = { "doctor", "Doctor" },
            test = function(t, strict)
                return (wordFn(t, strict and STRICT_HEAL_WORDS or HEAL_WORDS)) ~= nil
            end,
        },
    }

    -- getgc: cari tabel yang punya handleMafiaStab / setTargetCharacter (sekali per 15 s, mahal).
    local gcCache = { at = -100, list = nil }
    local function gcCandidates()
        if type(getgc) ~= "function" then
            return {}
        end
        if gcCache.list and now() - gcCache.at < 15 then
            return gcCache.list
        end
        local list = {}
        pcall(function()
            local objs = getgc(true)
            if type(objs) ~= "table" then
                return
            end
            local n = 0
            for _, v in pairs(objs) do
                n = n + 1
                if n > 400000 or #list >= 40 then
                    break
                end
                if type(v) == "table" then
                    local a = rawget(v, "handleMafiaStab")
                    local b = rawget(v, "setTargetCharacter")
                    if type(a) == "function" or type(b) == "function" then
                        list[#list + 1] = v
                    end
                end
            end
        end)
        gcCache.list, gcCache.at = list, now()
        return list
    end

    -- return host, strict
    local function findHost(kind)
        local h = HOSTS[kind]
        local m = req(h.path)
        if h.test(m, false) then
            return m, false
        end
        local rc = req("client.controllers.roleController")
        if type(rc) == "table" then
            for _, c in ipairs({ idx(rc, "roles"), idx(rc, "Roles"), rc }) do
                if type(c) == "table" then
                    for _, k in ipairs(h.keys) do
                        local r = idx(c, k)
                        if h.test(r, false) then
                            return r, false
                        end
                    end
                end
            end
            if h.test(rc, true) then
                return rc, true
            end
            -- role aktif yang disimpan controller di field yang namanya tidak kita tahu
            local okScan, hit = pcall(function()
                for _, v in pairs(rc) do
                    if type(v) == "table" and h.test(v, true) then
                        return v
                    end
                end
                return nil
            end)
            if okScan and hit then
                return hit, true
            end
        end
        for _, t in ipairs(gcCandidates()) do
            if h.test(t, true) then
                return t, true
            end
        end
        return nil, false
    end

    local function arity(fn)
        if type(debug) ~= "table" or type(debug.info) ~= "function" then
            return nil, nil
        end
        local ok, n, va = pcall(debug.info, fn, "a")
        if ok and type(n) == "number" then
            return n, va == true
        end
        return nil, nil
    end

    -- Set argumen berikutnya cuma dicoba kalau yang ini ERROR (konvensi salah). Return false = handler
    -- menolak (cooldown dsb.): tetap dihitung terpanggil, jangan dipanggil ulang dengan argumen lain.
    -- return ok, argsDipakai, nilaiReturn
    local function tryCalls(fn, sets)
        for _, args in ipairs(sets) do
            local ok, r = pcall(fn, table.unpack(args, 1, args.n))
            if ok then
                return true, args, r
            end
        end
        return false, nil, nil
    end

    -- return true (method, self dulu), false (fungsi biasa), nil (gagal)
    local function callSetter(host, fn, tChar)
        local n, va = arity(fn)
        local sets
        if n == 1 and not va then
            sets = { pack(tChar) }
        else
            sets = { pack(host, tChar), pack(tChar) }
        end
        local ok, used = tryCalls(fn, sets)
        if not ok then
            return nil
        end
        return used.n >= 2 and used[1] == host
    end

    local function fakeInput()
        local t = {}
        pcall(function()
            t.UserInputType = Enum.UserInputType.MouseButton1
            t.UserInputState = Enum.UserInputState.Begin
            t.KeyCode = Enum.KeyCode.Unknown
            t.Position = Vector3.zero
            t.Delta = Vector3.zero
        end)
        return t
    end

    -- Konvensi panggil berdasarkan numparams (debug.info "a"):
    -- 0 -> () / (self); 1 -> (self) kalau method-style, selain itu (char); 2 -> (self, char) / (char, player);
    -- >= 3 -> kemungkinan handler input (actionName, UserInputState.Begin, input).
    local function callAction(host, fn, style, st)
        local n, va = arity(fn)
        local char, plr = st.tChar, st.p
        local begin = nil
        pcall(function()
            begin = Enum.UserInputState.Begin
        end)
        local input = fakeInput()
        local sets
        if n == nil or (n == 0 and va) then
            if style == true then
                sets = { pack(host) }
            elseif style == false then
                sets = { pack(), pack(char) }
            else
                sets = { pack(host), pack(char) }
            end
        elseif n == 0 then
            sets = { pack() }
        elseif n == 1 then
            if style == true then
                sets = { pack(host) }
            elseif style == false then
                sets = { pack(char) }
            else
                sets = { pack(char), pack(host) }
            end
        elseif n == 2 then
            if style == false then
                sets = { pack(char, plr), pack(host, char) }
            else
                sets = { pack(host, char), pack(char, plr) }
            end
        elseif n == 3 and style ~= true then
            sets = { pack("NoctisENIX", begin, input), pack(host, "NoctisENIX", begin, input), pack(host, char, plr), pack(char, plr) }
        else
            sets = { pack(host, "NoctisENIX", begin, input), pack(host, char, plr), pack("NoctisENIX", begin, input) }
        end
        -- return terpanggil, menolak (return false)
        local ok, _, r = tryCalls(fn, sets)
        return ok, ok and r == false
    end

    ------------------------------------------------------------------
    -- ProximityPrompt
    ------------------------------------------------------------------
    local promptCache = { at = -100, list = {} }
    local function allPrompts()
        if now() - promptCache.at < 5 then
            return promptCache.list
        end
        local list = {}
        pcall(function()
            for _, d in ipairs(ctx.Workspace:GetDescendants()) do
                if d:IsA("ProximityPrompt") then
                    list[#list + 1] = d
                end
            end
        end)
        promptCache.list, promptCache.at = list, now()
        return list
    end

    local function promptPos(pr)
        local ok, pos = pcall(function()
            local parent = pr.Parent
            if not parent then
                return nil
            end
            if parent:IsA("Attachment") then
                return parent.WorldPosition
            elseif parent:IsA("BasePart") then
                return parent.CFrame.Position
            elseif parent:IsA("Model") then
                return parent:GetPivot().Position
            end
            return nil
        end)
        if ok then
            return pos
        end
        return nil
    end

    -- token teks prompt (ActionText + ObjectText + Name), nil kalau prompt mati / tidak terbaca
    local function promptWords(pr)
        local ok, toks = pcall(function()
            if pr.Enabled == false then
                return nil
            end
            return nameWords(tostring(pr.ActionText or "") .. " " .. tostring(pr.ObjectText or "") .. " " .. tostring(pr.Name or ""))
        end)
        if ok then
            return toks
        end
        return nil
    end

    -- prompt ambil item (Medkit, Banana, Knife, Flashlight ...) bukan aksi ke pemain
    local PICKUP_WORDS = { "pick", "pickup", "grab", "take", "collect", "equip", "loot", "buy" }

    -- true kalau prompt ada di dalam Tool (dicari sampai `stop`)
    local function inTool(pr, stop)
        local ok, r = pcall(function()
            local node = pr.Parent
            while node and node ~= stop do
                if node:IsA("Tool") then
                    return true
                end
                node = node.Parent
            end
            return false
        end)
        return not ok or r == true
    end

    -- Prop dunia: bukan di Tool, bukan di karakter pemain lain / NPC (Model yang punya Humanoid).
    local function worldProp(pr)
        local ok, r = pcall(function()
            local node = pr.Parent
            local hops = 0
            while node and node ~= ctx.Workspace and hops < 20 do
                if node:IsA("Tool") then
                    return false
                end
                if node:IsA("Model") and (Players:GetPlayerFromCharacter(node) or node:FindFirstChildOfClass("Humanoid")) then
                    return false
                end
                node = node.Parent
                hops = hops + 1
            end
            return true
        end)
        return ok and r == true
    end

    -- Urutan: prompt di badan target dulu, lalu kata yang lebih spesifik (urutan `words`), lalu yang terdekat.
    -- Badan target: `words` + `bodyWords` (kata umum seperti help / pick cuma boleh di sini).
    -- Dalam `radius` stud: cuma prop dunia (lihat worldProp), bukan prompt ambil item, cuma `words`.
    local function matchingPrompts(st, words, bodyWords, radius)
        local hits, seen = {}, {}
        local tChar, center = st.tChar, st.center
        local bodyList = {}
        for _, w in ipairs(words) do
            bodyList[#bodyList + 1] = w
        end
        for _, w in ipairs(bodyWords or {}) do
            bodyList[#bodyList + 1] = w
        end
        pcall(function()
            for _, d in ipairs(tChar:GetDescendants()) do
                if d:IsA("ProximityPrompt") and not seen[d] then
                    seen[d] = true
                    local toks = promptWords(d)
                    local i = toks and not inTool(d, tChar) and firstWord(toks, bodyList)
                    if i then
                        hits[#hits + 1] = { pr = d, score = i * 20 }
                    end
                end
            end
        end)
        if center then
            for _, pr in ipairs(allPrompts()) do
                if not seen[pr] then
                    seen[pr] = true
                    local pos = promptPos(pr)
                    local okD, d = pcall(function()
                        return (pos - center).Magnitude
                    end)
                    if pos and okD and d <= radius and worldProp(pr) then
                        local toks = promptWords(pr)
                        local i = toks and not firstWord(toks, PICKUP_WORDS) and firstWord(toks, words)
                        if i then
                            hits[#hits + 1] = { pr = pr, score = 1000 + i * 20 + d }
                        end
                    end
                end
            end
        end
        pcall(table.sort, hits, function(a, b)
            return a.score < b.score
        end)
        local out = {}
        for i, h in ipairs(hits) do
            out[i] = h.pr
        end
        return out
    end

    local function firePrompt(pr)
        if type(fireproximityprompt) == "function" then
            if pcall(fireproximityprompt, pr) then
                return "fireproximityprompt"
            end
        end
        local began = pcall(function()
            pr:InputHoldBegin()
        end)
        if began then
            local hold = 0
            pcall(function()
                hold = tonumber(pr.HoldDuration) or 0
            end)
            if hold > 0 then
                task.wait(hold + 0.05)
            end
            pcall(function()
                pr:InputHoldEnd()
            end)
            return "InputHold"
        end
        return nil
    end

    ------------------------------------------------------------------
    -- Strategi. Dua tahap supaya pencarian mahal (require, getgc, scan prompt) jalan SEBELUM teleport:
    --   prepare(st) -> "ready", run | "skip", reason      (dipanggil sebelum pindah)
    --   run()       -> "ok", method | "fail", method      (dipanggil saat sudah di belakang target)
    ------------------------------------------------------------------
    local function findTool(words)
        local places = { LocalPlayer.Character, LocalPlayer:FindFirstChildOfClass("Backpack") }
        for _, place in ipairs(places) do
            if place then
                for _, c in ipairs(place:GetChildren()) do
                    if c:IsA("Tool") then
                        local n = string.lower(tostring(c.Name))
                        for _, w in ipairs(words) do
                            if string.find(n, w, 1, true) then
                                return c
                            end
                        end
                    end
                end
            end
        end
        return nil
    end

    local function handlerStrategy(kind, actionPicker, notLoaded)
        return function(st)
            local host, strict = findHost(kind)
            if not host then
                return "skip", notLoaded
            end
            local name, fn = actionPicker(host, strict)
            if not fn then
                return "skip", notLoaded
            end
            local setFn = fnOf(host, "setTargetCharacter")
            local label = "handler:" .. name
            return "ready", function()
                local style = nil
                if setFn then
                    style = callSetter(host, setFn, st.tChar)
                end
                local called, refused = callAction(host, fn, style, st)
                if refused then
                    return "fail", label .. " (refused)"
                end
                if called then
                    return "ok", label
                end
                return "fail", label .. " (errored)"
            end
        end
    end

    local function promptStrategy(words, bodyWords)
        return function(st)
            local list = matchingPrompts(st, words, bodyWords, 12)
            if #list == 0 then
                return "skip", nil
            end
            return "ready", function()
                for _, pr in ipairs(list) do
                    if idx(pr, "Parent") ~= nil then
                        local how = firePrompt(pr)
                        if how then
                            return "ok", "prompt:" .. how
                        end
                    end
                end
                return "fail", "prompt (could not fire)"
            end
        end
    end

    local function toolStrategy(words)
        return function(st)
            local tool = findTool(words)
            if not tool then
                return "skip", nil
            end
            local label = "tool:" .. tostring(tool.Name)
            return "ready", function()
                if tool.Parent ~= st.char then
                    local okE = pcall(function()
                        st.hum:EquipTool(tool)
                    end)
                    if not okE then
                        return "fail", label .. " (could not equip)"
                    end
                    st.equipped = tool
                    task.wait()
                end
                local okA = pcall(function()
                    tool:Activate()
                end)
                if okA then
                    return "ok", label
                end
                return "fail", label .. " (could not use)"
            end
        end
    end

    -- Remote asli game (ReplicatedStorage.RoleNetworks.mafia.onStab / doctor.onHeal) lewat Net module.
    local function netStrategy(kind)
        -- Protokol strategi: tahap siapkan (sebelum teleport) return "ready", runner;
        -- runner dijalankan SETELAH teleport dan return "ok"/"fail", info.
        return function(st)
            local net = ctx.Net
            local fn = net and (kind == "stab" and net.stab or net.heal)
            if type(fn) ~= "function" then
                return "skip", nil
            end
            local remote = net.role and net.role(kind == "stab" and "mafia" or "doctor", kind == "stab" and "onStab" or "onHeal")
            if not remote then
                return "skip", nil
            end
            return "ready", function()
                local ok, method = fn(st.p)
                if ok then
                    return "ok", method
                end
                return "fail", "remote: " .. tostring(method)
            end
        end
    end

    local STAB_STRATEGIES = {
        netStrategy("stab"),
        handlerStrategy("mafia", function(host)
            return exactFn(host, STAB_FNS)
        end, MSG.stabNotLoaded),
        -- "knife" cuma untuk prompt di badan target (prompt Knife di dunia = ambil item)
        promptStrategy({ "stab", "kill", "attack" }, { "knife" }),
        toolStrategy({ "knife" }),
    }
    local HEAL_STRATEGIES = {
        netStrategy("heal"),
        handlerStrategy("doctor", function(host, strict)
            return wordFn(host, strict and STRICT_HEAL_WORDS or HEAL_WORDS)
        end, MSG.healNotLoaded),
        -- help / pick terlalu umum: cuma untuk prompt di badan pemain yang downed
        promptStrategy({ "heal", "revive", "save" }, { "help", "pick" }),
        toolStrategy({ "medkit", "med kit", "heal", "bandage", "syringe" }),
    }

    ------------------------------------------------------------------
    -- Role gate: true kalau boleh, plus catatan kalau role belum diketahui
    ------------------------------------------------------------------
    local function roleGate(want, wantTeam)
        if setting("ignoreRoleCheck", false) then
            return true, nil
        end
        local role, team = nil, nil
        if type(ctx.selfRole) == "function" then
            local ok, r, t = pcall(ctx.selfRole)
            if ok then
                role, team = r, t
            end
        end
        if type(role) == "string" and role ~= "" then
            local official = role
            pcall(function()
                official = Game.matchRole(role) or role
            end)
            return string.lower(official) == want, nil
        end
        local nt = nil
        if team ~= nil then
            pcall(function()
                nt = Game.normalizeTeam(team)
            end)
        end
        if nt and nt ~= wantTeam then
            return false, nil
        end
        return true, MSG.roleUnknown
    end

    local function withNote(text, note)
        if note then
            return text .. " (" .. note .. ")"
        end
        return text
    end

    ------------------------------------------------------------------
    -- Teleport -> aksi -> balik (dipakai Stab dan Heal). BOLEH yield.
    ------------------------------------------------------------------
    local function startPin(p, dist)
        return connect(RunService.Heartbeat, function()
            if not Busy.on then
                return
            end
            local char, _, root = body(LocalPlayer)
            local tcf = realTargetCF(p)
            if not (root and tcf) then
                return
            end
            local okD, dest = pcall(standCF, tcf, dist)
            if not okD then
                return
            end
            local okF, far = pcall(function()
                return (root.CFrame.Position - dest.Position).Magnitude > 1.5
            end)
            if okF and far then
                placeAt(char, root, dest)
            end
        end)
    end

    local function pollUntil(fn, timeout)
        local t0 = now()
        local tries = 0
        while true do
            local ok, r = pcall(fn)
            if ok and r then
                return true
            end
            tries = tries + 1
            if tries >= 60 or now() - t0 >= timeout then
                return false
            end
            task.wait(0.05)
        end
    end

    -- Berapa lama menunggu efek satu strategi sebelum coba yang berikutnya: minimal tsrConfirm,
    -- cukup untuk round-trip ke server kalau ping tinggi, maksimal 1 s.
    local function confirmWindow()
        local t = tonumber(setting("tsrConfirm", 0.3)) or 0.3
        local okP, ping = pcall(function()
            return LocalPlayer:GetNetworkPing()
        end)
        if okP and type(ping) == "number" and ping > 0 then
            t = math.max(t, math.min(ping * 2 + 0.1, 1))
        end
        return t
    end

    local function tripInner(op, st)
        -- 1. siapkan semua strategi selagi masih di posisi awal: require / getgc / scan prompt yang
        --    mahal tidak boleh bikin kita berdiri lama di belakang target
        local runners, reason = {}, nil
        for _, strat in ipairs(op.strategies) do
            local okP, status, a = pcall(strat, st)
            if not okP then
                warnOnce(op.kind .. "prep" .. tostring(status), status)
            elseif status == "ready" and type(a) == "function" then
                runners[#runners + 1] = a
            elseif status == "skip" and a and not reason then
                reason = a
            end
        end
        if #runners == 0 then
            -- tidak ada yang bisa dicoba: jangan teleport sama sekali
            Last.method = nil
            return false, withNote(reason or op.notLoaded, op.note)
        end
        -- target bisa sudah jalan selama prepare (require bisa yield)
        st.tcf = realTargetCF(st.p) or st.tcf
        local dist = tonumber(setting("tsrDistance", 3)) or 3
        local origin = st.root.CFrame
        st.origin = origin
        local okCF, dest = pcall(standCF, st.tcf, dist)
        if not okCF or not placeAt(st.char, st.root, dest) then
            return false, "Teleport failed."
        end
        st.moved = true
        st.pin = startPin(st.p, dist)
        -- 2 frame + jeda kecil: replikasi posisi karakter terpisah dari remote, server harus sudah
        -- lihat kita di dekat target sebelum remote aksi sampai
        task.wait()
        task.wait()
        local pre = tonumber(setting("tsrPre", 0.12)) or 0.12
        if pre > 0 then
            task.wait(pre)
        end
        -- 2. jalankan berurutan. "Tidak error" belum tentu berhasil (handler di tabel modul bisa return
        --    diam-diam, prompt bisa tidak bereaksi), jadi tunggu efeknya dulu sebelum lanjut / berhenti.
        local res = { ran = false, confirmed = false, method = nil, failMethod = nil }
        local confirm = confirmWindow()
        for _, run in ipairs(runners) do
            local okS, status, info = pcall(run)
            if not okS then
                warnOnce(op.kind .. "run" .. tostring(status), status)
            elseif status == "ok" then
                res.ran, res.method = true, info
                if pollUntil(op.check, confirm) then
                    res.confirmed = true
                    break
                end
            elseif not res.failMethod then
                res.failMethod = info
            end
        end
        if not res.confirmed then
            task.wait(tonumber(setting("tsrHold", 0.35)) or 0.35)
        end
        st.pin = disconnect(st.pin)
        -- selalu balik
        placeAt(st.char, st.root, origin)
        st.moved = false
        if st.equipped then
            pcall(function()
                st.hum:UnequipTools()
            end)
            st.equipped = nil
        end
        Last.method = res.method or res.failMethod
        if res.confirmed or pollUntil(op.check, op.verifyTime) then
            return true, withNote(op.success .. nameOf(st.p), op.note)
        end
        -- handler ada tapi error / menolak / tidak ada efek: bukan "belum ke-load"
        return false, withNote(op.none, op.note)
    end

    local function trip(op)
        local char, hum, root = myBody()
        if not char then
            return false, MSG.noBodyAct
        end
        if isSeated(hum) then
            return false, MSG.seated
        end
        local p = op.player
        ghostRestore()
        local tcf = realTargetCF(p)
        local tChar = p.Character
        if not (tcf and tChar) then
            return false, MSG.noTargetBody
        end
        local center = nil
        pcall(function()
            center = tcf.Position
        end)
        local st = { p = p, tChar = tChar, tcf = tcf, center = center, char = char, hum = hum, root = root }
        Busy.on = true
        Ghost.suspended = true
        -- Bring aktif: taruh target di posisi aslinya selama aksi (cek jarak / hitbox di client game)
        bringRestoreReal()
        local okRun, ok, msg = pcall(tripInner, op, st)
        -- finally: lepas pin, balik ke posisi awal kalau belum, lepas tool
        st.pin = disconnect(st.pin)
        if st.moved and st.origin and st.root.Parent then
            placeAt(st.char, st.root, st.origin)
        end
        if st.equipped then
            pcall(function()
                st.hum:UnequipTools()
            end)
        end
        Ghost.suspended = false
        Busy.on = false
        if not okRun then
            warnOnce("trip" .. tostring(ok), ok)
            return false, "Something went wrong, you were moved back."
        end
        return ok, msg
    end

    local function charDead(c)
        local ok, r = pcall(function()
            local h = c and c:FindFirstChildOfClass("Humanoid")
            return h ~= nil and h.Health <= 0
        end)
        return ok and r == true
    end

    -- Mati dihitung dari flag Dead / Health <= 0 di karakter yang sama. Target keluar game atau
    -- karakternya hilang BUKAN tanda tusukan kena.
    local function hurtState(p, tChar)
        return {
            downed = flag(p, "Downed"),
            dead = flag(p, "Dead") or charDead(tChar),
            wound = flag(p, "knifeWound"),
        }
    end

    function Actions.tpStabReturn()
        if Busy.on then
            return false, MSG.busy
        end
        local p = Actions.getTarget()
        if not p then
            return false, MSG.noTarget
        end
        local allowed, note = roleGate("mafia", "EVIL")
        if not allowed then
            return false, MSG.mafiaOnly
        end
        local tChar = p.Character
        local before = hurtState(p, tChar)
        return trip({
            kind = "stab",
            player = p,
            note = note,
            strategies = STAB_STRATEGIES,
            notLoaded = MSG.stabNotLoaded,
            none = MSG.stabNone,
            success = "Stab landed on ",
            verifyTime = 1,
            check = function()
                local n = hurtState(p, tChar)
                return (n.downed and not before.downed) or (n.dead and not before.dead) or (n.wound and not before.wound)
            end,
        })
    end

    function Actions.tpHealReturn()
        if Busy.on then
            return false, MSG.busy
        end
        local allowed, note = roleGate("doctor", "TOWN")
        if not allowed then
            return false, MSG.doctorOnly
        end
        local okN, p = pcall(nearestWith, "Downed")
        if not (okN and p) then
            return false, MSG.noDowned
        end
        return trip({
            kind = "heal",
            player = p,
            note = note,
            strategies = HEAL_STRATEGIES,
            notLoaded = MSG.healNotLoaded,
            none = MSG.healNone,
            success = "Saved ",
            verifyTime = 1.5,
            check = function()
                return not flag(p, "Downed") and alive(p)
            end,
        })
    end

    ------------------------------------------------------------------
    -- Status / cleanup
    ------------------------------------------------------------------
    ------------------------------------------------------------------
    -- Escape meeting seat + Stand on the table (v2.1)
    -- Game menahan semua orang di kursi (Workspace.Map.Seats) selama meeting.
    ------------------------------------------------------------------
    local Escape = { on = false, conn = nil, disabled = {} }

    local function seatsRoot()
        local map = workspace:FindFirstChild("Map")
        return map and map:FindFirstChild("Seats") or nil
    end

    local function unseatOnce()
        local char, hum, root = myBody()
        if not (hum and root) then
            return false
        end
        local seat = hum.SeatPart
        if seat then
            for _, w in ipairs(seat:GetChildren()) do
                if w.Name == "SeatWeld" and w:IsA("JointInstance") and (w.Part1 == root or w.Part0 == root) then
                    pcall(function()
                        w:Destroy()
                    end)
                end
            end
            pcall(function()
                hum.Sit = false
            end)
            pcall(function()
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
            end)
        end
        if root.Anchored then
            pcall(function()
                root.Anchored = false
            end)
        end
        return seat ~= nil
    end
    Actions.unseat = unseatOnce

    local function escapeOff()
        Escape.on = false
        Escape.conn = disconnect(Escape.conn)
        for seat in pairs(Escape.disabled) do
            pcall(function()
                seat.Disabled = false
            end)
        end
        Escape.disabled = {}
    end

    function Actions.setEscapeSeat(on)
        if not on then
            if not Escape.on then
                return true, "Seat escape is already off."
            end
            escapeOff()
            return true, "Seat escape off. The next meeting will seat you normally."
        end
        if Escape.on then
            return true, "Seat escape is already on."
        end
        local _, hum = myBody()
        if not hum then
            return false, MSG.noBodyAct or "You have no living character to move."
        end
        Escape.on = true
        -- Kursi dimatikan lokal biar nggak langsung kesedot duduk lagi pas jalan di dekatnya.
        local sr = seatsRoot()
        if sr then
            for _, d in ipairs(sr:GetDescendants()) do
                if (d:IsA("Seat") or d:IsA("VehicleSeat")) and not d.Disabled then
                    local ok = pcall(function()
                        d.Disabled = true
                    end)
                    if ok then
                        Escape.disabled[d] = true
                    end
                end
            end
        end
        Escape.conn = connect(RunService.Heartbeat, function()
            pcall(unseatOnce)
        end)
        local was = unseatOnce()
        return true, was and "You are out of your seat. Everyone can see you walking around."
            or "On. Whenever the game seats you, you get pulled back out."
    end

    -- Titik tengah lingkaran kursi, lalu raycast ke bawah buat cari permukaan meja.
    local function tableTop()
        local sr = seatsRoot()
        if not sr then
            return nil
        end
        local sum, n = Vector3.new(0, 0, 0), 0
        for _, d in ipairs(sr:GetDescendants()) do
            if d:IsA("BasePart") then
                sum = sum + d.Position
                n = n + 1
            end
        end
        if n == 0 then
            return nil
        end
        local center = sum / n
        local ignore = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p.Character then
                ignore[#ignore + 1] = p.Character
            end
        end
        local hitPos
        pcall(function()
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = ignore
            local res = workspace:Raycast(center + Vector3.new(0, 25, 0), Vector3.new(0, -60, 0), params)
            if res then
                hitPos = res.Position
            end
        end)
        return (hitPos or center) + Vector3.new(0, 3.2, 0)
    end

    function Actions.toTable()
        local char, hum, root = myBody()
        if not char then
            return false, MSG.noBodyAct or "You have no living character to move."
        end
        local pos = tableTop()
        if not pos then
            return false, "Meeting table not found on this map."
        end
        unseatOnce()
        local look = root.CFrame.LookVector
        local flat = Vector3.new(look.X, 0, look.Z)
        local cf = (flat.Magnitude > 0.01) and CFrame.new(pos, pos + flat) or CFrame.new(pos)
        if not placeAt(char, root, cf) then
            return false, "Teleport failed."
        end
        if hum.SeatPart then
            return true, "Moved, but the game is still holding your seat. Turn on Escape meeting seat."
        end
        return true, "Standing on the table."
    end

    function Actions.status()
        return {
            fakeCrawl = Crawl.on,
            ghost = Ghost.on,
            bring = Bring.on,
            target = Actions.getTarget(),
            lastMethod = Last.method,
            busy = Busy.on,
            escapeSeat = Escape.on,
        }
    end

    function Actions.stop()
        pcall(escapeOff)
        pcall(crawlOff)
        pcall(ghostOff, nil)
        pcall(bringOff, nil)
        for _, c in pairs(Shot.tracks) do
            stopTrack(c.track, 0.1)
            pcall(function()
                c.track:Destroy()
            end)
        end
        Shot.tracks = {}
        Shot.token = {}
        unbindRender(GHOST_BIND)
        unbindRender(BRING_BIND)
        return true, "Actions stopped."
    end

    -- Respawn: ghost mati, crawl dipasang ulang di Heartbeat berikutnya.
    pcall(function()
        connect(LocalPlayer.CharacterAdded, function()
            if Ghost.on then
                ghostOff("Ghost turned off (you respawned).")
            end
            if Crawl.on then
                crawlRelease()
                Crawl.hum = nil
            end
        end)
    end)
    pcall(function()
        connect(Players.PlayerRemoving, function(p)
            if p == Target.player then
                Target.player = nil
                if Bring.on then
                    bringOff("Target left, bring turned off.")
                end
            end
        end)
    end)

    -- Unload (Janitor) ikut matikan semuanya: render-step binding, track crawl yang looped, WalkSpeed.
    -- stop() idempotent, jadi aman kalau integrator juga memanggilnya sendiri.
    if type(ctx.track) == "function" then
        pcall(ctx.track, function()
            pcall(Actions.stop)
        end)
    end

    -- Hook khusus test
    Actions._test = {
        setClock = function(fn)
            clockFn = fn or os.clock
        end,
        state = function()
            return { Crawl = Crawl, Ghost = Ghost, Bring = Bring, Busy = Busy, Shot = Shot }
        end,
    }

    return Actions
end
-- <<< modules/actions.lua
end)()(ctx)

local function intelInfo(p)
    local ok, info = pcall(Intel.info, p)
    if not (ok and type(info) == "table") then
        return { status = {} }
    end
    local view = {
        role = info.role,
        team = info.team,
        confidence = info.confidence,
        reason = info.reason,
        disguise = info.disguise,
        status = type(info.status) == "table" and info.status or {},
    }
    -- Mode ketat (default): tebakan (likely / suspect) nggak ditampilkan sama sekali.
    if not S.showGuesses and view.confidence ~= "confirmed" then
        view.role, view.team, view.confidence, view.reason = nil, nil, nil, nil
    end
    return view
end

-- Nama karakter in-game (DisguiseName); kalau belum ada, DisplayName.
local function charName(p, info)
    info = info or intelInfo(p)
    if info.disguise and info.disguise ~= "" then
        return info.disguise
    end
    local okA, dn = pcall(Game.attr, p, "DisguiseName")
    if okA and type(dn) == "string" and dn ~= "" then
        return dn
    end
    return p.DisplayName
end

local function infoTeam(info)
    return info.team or (info.role and Game.teamOf(info.role)) or nil
end

ctx.Intel = Intel
ctx.nameOf = function(p)
    return charName(p)
end
local Votes = (function()
-- >>> modules/votes.lua
-- Votes: siapa nge-vote siapa, buat Vote ESP (tag + laser) dan daftar vote di tab Roles.
-- Semua sumber baca-saja:
--   tally    : ServiceNetworks.gameService.talliedVotes (getter, dipanggil client game sendiri buat
--              tanda vote di atas kepala), di-poll pelan.
--   event    : ServiceNetworks.gameService.votePlayer, kalau server menyiarkannya ke client.
--   pointing : ServiceNetworks.pointingService.updateArmPointing (RemoteEvent dari server), lengan
--              yang nunjuk = "laser" ke orang yang di-vote.
--   attr     : Intel.votes() (attribute talliedVotes / playerVotes) sebagai cadangan.
-- Bentuk payload belum pernah terekam isinya (cuma jumlahnya), jadi parser-nya toleran.
--
-- Dipanggil sebagai: local Votes = (<isi file ini>)(ctx); Votes.start()
return function(ctx)
    local V = { log = {}, last = nil, found = {} }
    local Players, LocalPlayer = ctx.Players, ctx.LocalPlayer
    local Net, Game = ctx.Net, ctx.Game

    -- Sumber yang lebih kuat nggak ditimpa sumber yang lebih lemah selama masih segar.
    local RANK = { attr = 1, pointing = 2, event = 3, tally = 4 }
    local FRESH = 30
    local POINT_TTL = 90

    local entries = {} -- [voter] = { target = Player, src = "pointing", t = os.clock() }
    local tallyCounts = {} -- [target] = jumlah dari server
    local tallyAt = -100
    local lastActivity = -100
    local inVote = false
    local alerted = {}
    local pollAt = -100
    local started = false

    local function now()
        return os.clock()
    end

    local function note(text)
        local l = V.log
        l[#l + 1] = string.format("[%.1f] %s", now(), text)
        if #l > 40 then
            table.remove(l, 1)
        end
    end

    local function playerFrom(v)
        if v == nil or type(v) == "boolean" then
            return nil
        end
        local ok, p = pcall(Net.playerFrom, v)
        return ok and p or nil
    end

    local function posOf(v)
        local t = typeof(v)
        if t == "Vector3" then
            return v
        elseif t == "CFrame" then
            return v.Position
        end
        return nil
    end

    -- Pemain yang badannya paling dekat ke titik (titik ujung "laser").
    function V.nearestPlayerTo(pos, exclude, maxDist)
        local best, bestD = nil, maxDist or 6
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= exclude then
                local c = p.Character
                local root = c and (c:FindFirstChild("HumanoidRootPart") or c:FindFirstChild("Head"))
                if root then
                    local d = (root.Position - pos).Magnitude
                    if d < bestD then
                        best, bestD = p, d
                    end
                end
            end
        end
        return best
    end

    local function settings()
        return ctx.S or {}
    end

    local function nameOf(p)
