        for i = 1, args.n do
            local v = args[i]
            if typeof(v) == "table" then
                local mapped = {}
                if mapPairs(v, mapped) > 0 and not pointer then
                    return mapped
                end
                for _, k in ipairs(VOTER_KEYS) do
                    consider(rawget(v, k))
                end
                for _, k in ipairs(TARGET_KEYS) do
                    consider(rawget(v, k))
                end
                for _, k in ipairs(POS_KEYS) do
                    consider(rawget(v, k))
                end
                for _, x in ipairs(v) do
                    consider(x)
                end
